    def _load_expert_tensor(
        self, name: str, tensor: torch.Tensor
    ) -> set[str]:
        """Load one fused all-experts tensor via RoutedExperts.weight_loader.

        Handles the stacked layouts: 3-D [E, 2*I, H] weights/block scales
        (split into w1/w3 halves), 2-D [E, 2] per-shard global scales, and
        1-D [E] per-expert scalars. EP filtering and TP sharding happen inside
        the quant method's weight_loader.
        """
        rel = name.removeprefix("experts.")
        match = _EXPERT_TENSOR_PATTERN.fullmatch(rel)
        routed_experts = self.experts.routed_experts
        param = getattr(routed_experts, rel, None) if match else None
        if match is None or param is None:
            raise ValueError(
                f"Unsupported expert weight {name!r}: expected fused "
                "experts.(w13|w2)_(weight|weight_scale|weight_scale_2|input_scale)"
            )
        proj, _ = match.groups()
        loaded: set[str] = set()
        shard_ids = ("w1", "w3") if proj == "w13" else ("w2",)
        for shard_pos, shard_id in enumerate(shard_ids):
            if proj == "w13" and tensor.dim() == 3:
                shard = tensor.chunk(2, dim=1)[shard_pos]
            elif proj == "w13" and tensor.dim() == 2:
                shard = tensor[:, shard_pos]
            else:
                shard = tensor
            for expert_id, expert_weight in enumerate(shard.unbind(0)):
                if routed_experts.weight_loader(
                    param=param,
                    loaded_weight=expert_weight,
                    weight_name=rel,
                    shard_id=shard_id,
                    expert_id=expert_id,
                    return_success=True,
                ):
                    loaded.add(f"experts.routed_experts.{rel}")
        return loaded

    def load_weights(self, weights: Iterable[tuple[str, torch.Tensor]]) -> set[str]:
        loaded: set[str] = set()
        deferred: list[tuple[str, torch.Tensor]] = []
        for name, tensor in weights:
            if name.startswith("experts."):
                loaded.update(self._load_expert_tensor(name, tensor))
                continue
            if name == "router.weight" and tensor.dim() == 2:
                # The checkpoint stores the router as [hidden, num_experts];
                # ReplicatedLinear expects [num_experts, hidden].
                param = self.router.weight
                if tensor.shape != param.shape and tensor.t().shape == param.shape:
                    tensor = tensor.t().contiguous()
            deferred.append((name, tensor))
        loader = AutoWeightsLoader(self)
        loaded.update(loader.load_weights(iter(deferred)))
        return loaded


